create or replace function public.update_journal_draft(p_organization_id uuid,p_journal_id uuid,p_journal_date date,p_reference text,p_description text,p_lines jsonb,p_branch_id uuid default null) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare x jsonb; n int:=0; begin perform public.assert_journal_draft(p_organization_id,p_journal_id); if p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id) then raise exception 'invalid_branch'; end if; if exists(select 1 from jsonb_array_elements(p_lines) x join public.accounts a on a.id=(x->>'account_id')::uuid where a.organization_id<>p_organization_id or not a.is_active or not a.allow_manual_posting) then raise exception 'invalid_posting_account'; end if; update public.journal_entries set journal_date=p_journal_date,branch_id=p_branch_id,reference=nullif(trim(p_reference),''),description=trim(p_description) where id=p_journal_id; delete from public.journal_lines where journal_entry_id=p_journal_id; for x in select * from jsonb_array_elements(p_lines) loop n:=n+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount) values(p_organization_id,p_journal_id,n,(x->>'account_id')::uuid,nullif(x->>'description',''),coalesce((x->>'debit')::numeric,0),coalesce((x->>'credit')::numeric,0)); end loop; perform public.accounting_audit(p_organization_id,'journal.updated','journal_entry',p_journal_id); end; $$;
create or replace function public.delete_journal_draft(p_organization_id uuid,p_journal_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_journal_draft(p_organization_id,p_journal_id); delete from public.journal_entries where id=p_journal_id and organization_id=p_organization_id; perform public.accounting_audit(p_organization_id,'journal.deleted','journal_entry',p_journal_id); end; $$;
create or replace function public.get_trial_balance(p_organization_id uuid,p_as_of date default current_date) returns table(account_id uuid,account_code text,account_name text,debit numeric,credit numeric) language sql security definer set search_path=pg_catalog,public as $$ select a.id,a.code,a.name,coalesce(sum(l.debit_amount),0),coalesce(sum(l.credit_amount),0) from public.accounts a join public.journal_lines l on l.account_id=a.id join public.journal_entries j on j.id=l.journal_entry_id where a.organization_id=p_organization_id and j.organization_id=p_organization_id and j.status in ('posted','reversed') and j.journal_date<=p_as_of and public.is_active_org_member(p_organization_id) group by a.id,a.code,a.name having coalesce(sum(l.debit_amount),0)<>0 or coalesce(sum(l.credit_amount),0)<>0 order by a.code $$;
create or replace function public.get_general_ledger(p_organization_id uuid,p_account_id uuid,p_from date,p_to date) returns table(journal_date date,journal_number text,reference text,description text,debit numeric,credit numeric,running_balance numeric) language sql security definer set search_path=pg_catalog,public as $$ select j.journal_date,j.journal_number,j.reference,coalesce(l.description,j.description),l.debit_amount,l.credit_amount,sum(l.debit_amount-l.credit_amount) over(order by j.journal_date,j.created_at,l.line_number) from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.organization_id=p_organization_id and l.account_id=p_account_id and j.status in ('posted','reversed') and j.journal_date between p_from and p_to and public.is_active_org_member(p_organization_id) order by j.journal_date,j.created_at,l.line_number $$;
revoke all on function public.update_journal_draft(uuid,uuid,date,text,text,jsonb,uuid),public.delete_journal_draft(uuid,uuid),public.get_trial_balance(uuid,date),public.get_general_ledger(uuid,uuid,date,date) from public,anon;
grant execute on function public.update_journal_draft(uuid,uuid,date,text,text,jsonb,uuid),public.delete_journal_draft(uuid,uuid),public.get_trial_balance(uuid,date),public.get_general_ledger(uuid,uuid,date,date) to authenticated;
